/// Raven `InitSiegeMode`.
///
/// Source: `oracle/codemp/game/g_saga.c:96-373`
pub fn InitSiegeMode(ctx: &mut GameContext) {
    unsafe {
        let mut mapname: vmCvar_t = vmCvar_t::zeroed();
        let mut teamIcon: [c_char; 128] = [0; 128];
        let mut goalreq: [c_char; 64] = [0; 64];
        let mut teams: [c_char; 2048] = [0; 2048];
        let mut objective: [c_char; MAX_SIEGE_INFO_SIZE as usize] =
            [0; MAX_SIEGE_INFO_SIZE as usize];
        let mut objecStr: [c_char; 8192] = [0; 8192];
        let mut len: c_int = 0;
        let mut objectiveNumTeam1: c_int = 0;
        let mut objectiveNumTeam2: c_int = 0;
        let mut f: fileHandle_t = 0;

        'body: {
            if ctx.world.cvars.g_gametype.integer != GT_SIEGE {
                break 'body;
            }

            // reset
            SiegeSetCompleteData(ctx, 0);

            // get pers data in case it existed from last level
            if ctx.world.cvars.g_siegeTeamSwitch.integer != 0 {
                trap::SiegePersGet(
                    ctx.engine,
                    mp_abi::game::syscalls::G_SIEGEPERSGET::GSiegepersgetArgs::new(
                        &mut ctx.world.globals.g_siegePersistant as *mut siegePers_t,
                    ),
                );
                if ctx.world.globals.g_siegePersistant.beatingTime != 0 {
                    trap::SetConfigstring(
                        ctx.engine,
                        CS_SIEGE_TIMEOVERRIDE,
                        &format!("{}", ctx.world.globals.g_siegePersistant.lastTime),
                    );
                } else {
                    trap::SetConfigstring(ctx.engine, CS_SIEGE_TIMEOVERRIDE, "0");
                }
            } else {
                // hmm, ok, nothing.
                trap::SetConfigstring(ctx.engine, CS_SIEGE_TIMEOVERRIDE, "0");
            }

            ctx.world.globals.imperial_goals_completed = 0;
            ctx.world.globals.rebel_goals_completed = 0;

            trap::Cvar_Register(
                ctx.engine,
                Some(&mut mapname),
                "mapname",
                "",
                CVAR_SERVERINFO | CVAR_ROM,
            );

            let levelname_s = format!(
                "maps/{}.siege\0",
                cstr_from_chars(&mapname.string).to_string_lossy()
            );

            if levelname_s.is_empty() || levelname_s.as_bytes()[0] == 0 {
                break 'body;
            }

            let levelname_c = levelname_s.trim_end_matches('\0');
            len = trap::FS_FOpenFile(ctx.engine, levelname_c, &mut f, FS_READ);

            if f == 0 || len >= MAX_SIEGE_INFO_SIZE {
                break 'body;
            }

            trap::FS_Read(
                ctx.engine,
                &mut ctx.world.bg_state.siege_info[..len as usize],
                f,
            );

            trap::FS_FCloseFile(ctx.engine, f);

            ctx.world.bg_state.siege_valid = 1;

            // See if players should be specs or ingame preround
            if BG_SiegeGetPairedValue(
                ctx.world.bg_state.siege_info.as_mut_ptr() as *mut c_char,
                b"preround_state\0".as_ptr() as *mut c_char,
                teams.as_mut_ptr(),
            ) != 0
            {
                if teams[0] != 0 {
                    ctx.world.globals.g_preroundState = atoi(teams.as_ptr());
                }
            }

            if BG_SiegeGetValueGroup(
                ctx.world.bg_state.siege_info.as_mut_ptr() as *mut c_char,
                b"Teams\0".as_ptr() as *mut c_char,
                teams.as_mut_ptr(),
            ) != 0
            {
                if ctx.world.cvars.g_siegeTeam1.string[0] != 0
                    && Q_stricmp(
                        ctx.world.cvars.g_siegeTeam1.string.as_ptr(),
                        b"none\0".as_ptr() as *const c_char,
                    ) != 0
                {
                    // check for override
                    write_cstr_field(
                        &mut ctx.world.globals.team1,
                        &cstr_from_chars(&ctx.world.cvars.g_siegeTeam1.string).to_string_lossy(),
                    );
                } else {
                    // otherwise use level default
                    BG_SiegeGetPairedValue(
                        teams.as_mut_ptr(),
                        b"team1\0".as_ptr() as *mut c_char,
                        ctx.world.globals.team1.as_mut_ptr(),
                    );
                }

                if ctx.world.cvars.g_siegeTeam2.string[0] != 0
                    && Q_stricmp(
                        ctx.world.cvars.g_siegeTeam2.string.as_ptr(),
                        b"none\0".as_ptr() as *const c_char,
                    ) != 0
                {
                    write_cstr_field(
                        &mut ctx.world.globals.team2,
                        &cstr_from_chars(&ctx.world.cvars.g_siegeTeam2.string).to_string_lossy(),
                    );
                } else {
                    BG_SiegeGetPairedValue(
                        teams.as_mut_ptr(),
                        b"team2\0".as_ptr() as *mut c_char,
                        ctx.world.globals.team2.as_mut_ptr(),
                    );
                }
            } else {
                G_Error(ctx, "Siege teams not defined");
            }

            if BG_SiegeGetValueGroup(
                ctx.world.bg_state.siege_info.as_mut_ptr() as *mut c_char,
                ctx.world.globals.team2.as_mut_ptr(),
                ctx.world.globals.gParseObjectives.as_mut_ptr(),
            ) != 0
            {
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"TeamIcon\0".as_ptr() as *mut c_char,
                    teamIcon.as_mut_ptr(),
                ) != 0
                {
                    trap::Cvar_Set(
                        ctx.engine,
                        "team2_icon",
                        &cstr_from_chars(&teamIcon).to_string_lossy(),
                    );
                }

                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"RequiredObjectives\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    ctx.world.globals.rebel_goals_required = atoi(goalreq.as_ptr());
                }
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"Timed\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    ctx.world.globals.rebel_time_limit = atoi(goalreq.as_ptr()) * 1000;
                    if ctx.world.cvars.g_siegeTeamSwitch.integer != 0
                        && ctx.world.globals.g_siegePersistant.beatingTime != 0
                    {
                        ctx.world.globals.gRebelCountdown =
                            ctx.world.level.time + ctx.world.globals.g_siegePersistant.lastTime;
                    } else {
                        ctx.world.globals.gRebelCountdown =
                            ctx.world.level.time + ctx.world.globals.rebel_time_limit;
                    }
                }
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"attackers\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    ctx.world.globals.rebel_attackers = atoi(goalreq.as_ptr());
                }
            }

            if BG_SiegeGetValueGroup(
                ctx.world.bg_state.siege_info.as_mut_ptr() as *mut c_char,
                ctx.world.globals.team1.as_mut_ptr(),
                ctx.world.globals.gParseObjectives.as_mut_ptr(),
            ) != 0
            {
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"TeamIcon\0".as_ptr() as *mut c_char,
                    teamIcon.as_mut_ptr(),
                ) != 0
                {
                    trap::Cvar_Set(
                        ctx.engine,
                        "team1_icon",
                        &cstr_from_chars(&teamIcon).to_string_lossy(),
                    );
                }

                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"RequiredObjectives\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    ctx.world.globals.imperial_goals_required = atoi(goalreq.as_ptr());
                }
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"Timed\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    if ctx.world.globals.rebel_time_limit != 0 {
                        crate::g_main::Com_Printf("Tried to set imperial time limit, but there's already a rebel time limit!\nOnly one team can have a time limit.\n");
                    } else {
                        ctx.world.globals.imperial_time_limit = atoi(goalreq.as_ptr()) * 1000;
                        if ctx.world.cvars.g_siegeTeamSwitch.integer != 0
                            && ctx.world.globals.g_siegePersistant.beatingTime != 0
                        {
                            ctx.world.globals.gImperialCountdown =
                                ctx.world.level.time + ctx.world.globals.g_siegePersistant.lastTime;
                        } else {
                            ctx.world.globals.gImperialCountdown =
                                ctx.world.level.time + ctx.world.globals.imperial_time_limit;
                        }
                    }
                }
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"attackers\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    ctx.world.globals.imperial_attackers = atoi(goalreq.as_ptr());
                }
            }

            // Load the player class types
            BG_SiegeLoadClasses(
                core::ptr::null_mut(),
                &mut ctx.world.bg_state,
                &crate::bg_channel::GameBgTraps::new(ctx.engine),
            );

            if ctx.world.bg_state.bgNumSiegeClasses == 0 {
                G_Error(ctx, "Couldn't find any player classes for Siege");
            }

            // Now load the teams since we have class data.
            BG_SiegeLoadTeams(
                &mut ctx.world.bg_state,
                &crate::bg_channel::GameBgTraps::new(ctx.engine),
            );

            if ctx.world.bg_state.bgNumSiegeTeams == 0 {
                G_Error(ctx, "Couldn't find any player teams for Siege");
            }

            // Get and set the team themes for each team.
            if BG_SiegeGetValueGroup(
                ctx.world.bg_state.siege_info.as_mut_ptr() as *mut c_char,
                ctx.world.globals.team1.as_mut_ptr(),
                ctx.world.globals.gParseObjectives.as_mut_ptr(),
            ) != 0
            {
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"UseTeam\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    BG_SiegeSetTeamTheme(
                        SIEGETEAM_TEAM1,
                        goalreq.as_mut_ptr(),
                        &mut ctx.world.bg_state,
                    );
                }

                // Now count up the objectives for this team.
                let mut i: c_int = 1;
                write_cstr_field(&mut objecStr, &format!("Objective{}", i));
                while BG_SiegeGetValueGroup(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    objecStr.as_mut_ptr(),
                    objective.as_mut_ptr(),
                ) != 0
                {
                    objectiveNumTeam1 += 1;
                    i += 1;
                    write_cstr_field(&mut objecStr, &format!("Objective{}", i));
                }
            }
            if BG_SiegeGetValueGroup(
                ctx.world.bg_state.siege_info.as_mut_ptr() as *mut c_char,
                ctx.world.globals.team2.as_mut_ptr(),
                ctx.world.globals.gParseObjectives.as_mut_ptr(),
            ) != 0
            {
                if BG_SiegeGetPairedValue(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    b"UseTeam\0".as_ptr() as *mut c_char,
                    goalreq.as_mut_ptr(),
                ) != 0
                {
                    BG_SiegeSetTeamTheme(
                        SIEGETEAM_TEAM2,
                        goalreq.as_mut_ptr(),
                        &mut ctx.world.bg_state,
                    );
                }

                let mut i: c_int = 1;
                write_cstr_field(&mut objecStr, &format!("Objective{}", i));
                while BG_SiegeGetValueGroup(
                    ctx.world.globals.gParseObjectives.as_mut_ptr(),
                    objecStr.as_mut_ptr(),
                    objective.as_mut_ptr(),
                ) != 0
                {
                    objectiveNumTeam2 += 1;
                    i += 1;
                    write_cstr_field(&mut objecStr, &format!("Objective{}", i));
                }
            }

            // Set the configstring to show status of all current objectives
            let mut cfg = String::from("t1");
            while objectiveNumTeam1 > 0 {
                cfg.push_str("-0");
                objectiveNumTeam1 -= 1;
            }
            cfg.push_str("|t2");
            while objectiveNumTeam2 > 0 {
                cfg.push_str("-0");
                objectiveNumTeam2 -= 1;
            }
            write_cstr_field(&mut ctx.world.globals.gObjectiveCfgStr, &cfg);

            trap::SetConfigstring(ctx.engine, CS_SIEGE_OBJECTIVES, &cfg);

            // precache saber data for classes that use sabers on both teams
            let mut callbacks = crate::bg_channel::GameCallbacksImpl {
                // SEAM-BG-REENTRY (DEC-28, sanctioned) — GameCallbacksImpl.world is a `*mut GameWorld`
                // field aliasing bg_state; a raw store is required (bg-seam re-entry).
                world: ctx.world_raw(),
                engine: ctx.engine,
            };
            BG_PrecacheSabersForSiegeTeam(
                SIEGETEAM_TEAM1,
                &mut ctx.world.bg_state,
                &crate::bg_channel::GameBgTraps::new(ctx.engine),
                &mut callbacks,
            );
            BG_PrecacheSabersForSiegeTeam(
                SIEGETEAM_TEAM2,
                &mut ctx.world.bg_state,
                &crate::bg_channel::GameBgTraps::new(ctx.engine),
                &mut callbacks,
            );

            G_SiegeRegisterWeaponsAndHoldables(ctx, SIEGETEAM_TEAM1);
            G_SiegeRegisterWeaponsAndHoldables(ctx, SIEGETEAM_TEAM2);

            return;
        }

        // failure:
        ctx.world.bg_state.siege_valid = 0;
    }
}

/// Raven `G_SiegeSetObjectiveComplete`.
///
/// Source: `oracle/codemp/game/g_saga.c:375-427`
pub fn G_SiegeSetObjectiveComplete(
    ctx: &mut GameContext,
    team: c_int,
    objective: c_int,
    failIt: qboolean,
) {
    unsafe {
        let buf = ctx.world.globals.gObjectiveCfgStr.as_mut_ptr();
        let buf_len = cstr_from_chars(&ctx.world.globals.gObjectiveCfgStr)
            .to_bytes()
            .len();
        let needle: &[u8] = if team == SIEGETEAM_TEAM1 {
            b"t1"
        } else if team == SIEGETEAM_TEAM2 {
            b"t2"
        } else {
            b""
        };

        let mut p: *mut c_char = core::ptr::null_mut();
        if !needle.is_empty() {
            let mut i = 0usize;
            while i + needle.len() <= buf_len {
                if core::slice::from_raw_parts(buf.add(i) as *const u8, needle.len()) == needle {
                    p = buf.add(i);
                    break;
                }
                i += 1;
            }
        }

        if p.is_null() {
            // Raven: assert(0); return;
            return;
        }

        let mut onObjective: c_int = 0;

        // Parse from the beginning of this team's objectives until we get to
        // the desired objective number.
        while !p.is_null() && *p != 0 && *p != b'|' as c_char {
            if *p == b'-' as c_char {
                onObjective += 1;
            }

            if onObjective == objective {
                // this is the one we want; move to the status char.
                p = p.add(1);

                if failIt != 0 {
                    *p = b'0' as c_char;
                } else {
                    *p = b'1' as c_char;
                }
                break;
            }

            p = p.add(1);
        }

        // Now re-update the configstring.
        trap::SetConfigstring(
            ctx.engine,
            CS_SIEGE_OBJECTIVES,
            &cstr_from_chars(&ctx.world.globals.gObjectiveCfgStr).to_string_lossy(),
        );
    }
}

/// Raven `G_SiegeGetCompletionStatus` — qtrue if objective is currently complete.
///
/// Source: `oracle/codemp/game/g_saga.c:430-480`
pub fn G_SiegeGetCompletionStatus(
    ctx: &mut GameContext,
    team: c_int,
    objective: c_int,
) -> qboolean {
    unsafe {
        let buf = ctx.world.globals.gObjectiveCfgStr.as_mut_ptr();
        let buf_len = cstr_from_chars(&ctx.world.globals.gObjectiveCfgStr)
            .to_bytes()
            .len();
        let needle: &[u8] = if team == SIEGETEAM_TEAM1 {
            b"t1"
        } else if team == SIEGETEAM_TEAM2 {
            b"t2"
        } else {
            b""
        };

        let mut p: *mut c_char = core::ptr::null_mut();
        if !needle.is_empty() {
            let mut i = 0usize;
            while i + needle.len() <= buf_len {
                if core::slice::from_raw_parts(buf.add(i) as *const u8, needle.len()) == needle {
                    p = buf.add(i);
                    break;
                }
                i += 1;
            }
        }

        if p.is_null() {
            // Raven: assert(0); return qfalse;
            return qfalse;
        }

        let mut onObjective: c_int = 0;

        while !p.is_null() && *p != 0 && *p != b'|' as c_char {
            if *p == b'-' as c_char {
                onObjective += 1;
            }

            if onObjective == objective {
                p = p.add(1);

                // return qtrue if it's '1', qfalse if it's anything else
                if *p == b'1' as c_char {
                    return qtrue;
                } else {
                    return qfalse;
                }
            }

            p = p.add(1);
        }

        qfalse
    }
}

/// Raven `UseSiegeTarget` — use the player who triggered the object to fire the
/// objective's target.
///
/// Source: `oracle/codemp/game/g_saga.c:482-526`
pub fn UseSiegeTarget(
    ctx: &mut GameContext,
    other: Option<EntityId>,
    en: Option<EntityId>,
    target: *mut c_char,
) {
    // Raven: "looks like we don't have access to a player, so just use
    // the activating entity" — when `en` has no client, all three uses
    // below (self-use test, GlobalUse activator/owner, inuse guard) target
    // `other` instead.
    let ent: Option<EntityId> = match en {
        Some(en_id) if !ctx.world.entity(en_id).client.is_null() => Some(en_id),
        _ => other,
    };

    if en.is_none() {
        return;
    }
    if target.is_null() {
        return;
    }

    let targetname_ofs = core::mem::offset_of!(gentity_t, targetname) as c_int;

    let mut t: Option<EntityId> = None;
    loop {
        let t_raw = G_Find(ctx, t, targetname_ofs, target as *const c_char);
        t = ctx.entity_id_of(t_raw);
        let Some(t_id) = t else {
            break;
        };
        if t == ent {
            // G_Printf("WARNING: Entity used itself.\n") — no format args.
            crate::g_main::G_Printf(ctx, "WARNING: Entity used itself.\n");
        } else if !ctx.world.entity(t_id).use_.is_none() {
            GlobalUse(ctx, t, ent, ent);
        }
        // Raven derefs `ent` unconditionally here; when `ent` is null (no client
        // and no `other`) that is a null deref (UB) — unreachable in practice, so
        // the `Some` guard preserves the defined path (porting-rules §19).
        if let Some(ent_id) = ent {
            if ctx.world.entity(ent_id).inuse == 0 {
                crate::g_main::G_Printf(ctx, "entity was removed while using targets\n");
                return;
            }
        }
    }
}

// `SVF_BROADCAST` (`crate::g_public_consts`), `PMF_FOLLOW`
// (`mp_qshared::…::pm_flags`), `CONTENTS_NODROP`/`CONTENTS_TRIGGER`/
// `MASK_PLAYERSOLID` (`mp_qshared::shared::surface_flags`) all resolve via the
// crate prelude glob; the shadowing local copies (and their stale "not yet
// ported" notes) were removed by the placeholder-const sweep.

/// Raven `SiegeBroadcast_OBJECTIVECOMPLETE`.
///
/// Source: `oracle/codemp/game/g_saga.c:528-540`
pub fn SiegeBroadcast_OBJECTIVECOMPLETE(
    ctx: &mut GameContext,
    team: c_int,
    client: c_int,
    objective: c_int,
) {
    let nomatter: vec3_t = [0.0, 0.0, 0.0];

    let te = G_TempEntity(
        ctx,
        nomatter,
        entity_event_t::EV_SIEGE_OBJECTIVECOMPLETE as c_int,
    );
    let te = ctx.world.entity_mut(te);
    te.r.svFlags |= SVF_BROADCAST;
    te.s.eventParm = team;
    te.s.weapon = client;
    te.s.trickedentindex = objective;
}

/// Raven `SiegeBroadcast_ROUNDOVER`.
